package core

import (
	"bytes"
	"encoding/binary"
	"hash/crc32"
	"lmtools/internal/imagetest"
	"os"
	"path/filepath"
	"testing"
)

func TestImageContainerValidationPreservesArithmeticJPEG(t *testing.T) {
	// Generated by cjpeg -arithmetic and independently decoded by libjpeg.
	// The Go decoder does not implement this valid JPEG coding method.
	data := imagetest.ArithmeticJPEG
	path := filepath.Join(t.TempDir(), "arithmetic.jpg")
	if err := os.WriteFile(path, data, 0o600); err != nil {
		t.Fatal(err)
	}
	image, err := LoadImageFile(path, len(data))
	if err != nil {
		t.Fatal(err)
	}
	if image.URL != ImageDataURL("image/jpeg", data) {
		t.Fatal("JPEG bytes changed")
	}
}

func TestUnsupportedJPEGStillRequiresCompleteFrameAndScan(t *testing.T) {
	data := imagetest.ArithmeticJPEG
	frame := bytes.Index(data, []byte{0xff, 0xc9})
	if frame < 0 {
		t.Fatal("fixture has no arithmetic JPEG frame")
	}
	end := frame + 2 + int(binary.BigEndian.Uint16(data[frame+2:]))
	missingFrame := append(append([]byte(nil), data[:frame]...), data[end:]...)
	zeroWidth := append([]byte(nil), data...)
	zeroWidth[frame+7], zeroWidth[frame+8] = 0, 0
	missingHeight := append([]byte(nil), data...)
	missingHeight[frame+5], missingHeight[frame+6] = 0, 0
	withHeight := append(append([]byte(nil), missingHeight[:len(data)-2]...), 0xff, 0xdc, 0, 4, 0, 2, 0xff, 0xd9)
	if err := validateImageContainer(withHeight, "image/jpeg"); err != nil {
		t.Fatalf("deferred JPEG height rejected: %v", err)
	}
	zeroLineCount := append([]byte(nil), withHeight...)
	zeroLineCount[len(zeroLineCount)-3] = 0
	missingComponents := append([]byte(nil), data...)
	missingComponents[frame+9] = 0
	for name, damaged := range map[string][]byte{
		"truncated":          data[:len(data)-2],
		"missing frame":      missingFrame,
		"zero width":         zeroWidth,
		"missing height":     missingHeight,
		"zero line count":    zeroLineCount,
		"truncated DNL":      withHeight[:len(withHeight)-3],
		"missing components": missingComponents,
	} {
		t.Run(name, func(t *testing.T) {
			if err := validateImageContainer(damaged, "image/jpeg"); err == nil {
				t.Fatal("damaged JPEG container accepted")
			}
		})
	}
}

func TestImageContainerValidationRejectsDamagedStructure(t *testing.T) {
	png := append([]byte(nil), imagetest.PNG...)
	png[len(png)-1] ^= 0xff // IEND CRC, beyond DecodeConfig's stopping point.
	webp := append([]byte(nil), imagetest.WebP...)
	binary.LittleEndian.PutUint32(webp[16:], ^uint32(0))
	gif := append([]byte(nil), imagetest.GIF...)
	gif[len(gif)-2] = 255 // Image-data terminator now claims a missing data block.
	for _, fixture := range []struct {
		mediaType string
		data      []byte
	}{
		{"image/png", png}, {"image/webp", webp}, {"image/gif", gif},
	} {
		if err := validateImageContainer(fixture.data, fixture.mediaType); err == nil {
			t.Fatalf("damaged %s container accepted", fixture.mediaType)
		}
	}
}

func TestImageContainerValidationAllocatesNoPixelBuffer(t *testing.T) {
	data := append([]byte(nil), imagetest.PNG...)
	// A canvas this size would need several gigabytes when decoded. The
	// existing tiny IDAT deliberately exercises the documented boundary:
	// container validation leaves compressed pixel decoding to the provider.
	binary.BigEndian.PutUint32(data[16:], 32768)
	binary.BigEndian.PutUint32(data[20:], 32768)
	binary.BigEndian.PutUint32(data[29:], crc32.ChecksumIEEE(data[12:29]))
	if err := validateImageContainer(data, "image/png"); err != nil {
		t.Fatalf("large container configuration rejected: %v", err)
	}
	// Configuration parsing remains a small fixed cost even though declared
	// raster storage is large. This pins the deliberate absence of decoding.
	if allocs := testing.AllocsPerRun(5, func() {
		if err := validateImageContainer(data, "image/png"); err != nil {
			panic(err)
		}
	}); allocs > 20 {
		t.Fatalf("configuration/container validation allocated %g objects", allocs)
	}
}
